/// The arguments of a `lazy` body: evaluated when the body asks, as Go's row versions do.
pub trait Args {
    /// `len(b.args)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn len(&self) -> usize;
    /// Whether there are no arguments.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn is_empty(&self) -> bool {
        self.len() == 0
    }
    /// `b.args[i].EvalInt(ctx, row)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn int(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<i64>, Error>;
    /// `b.args[i].EvalReal(ctx, row)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn real(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<f64>, Error>;
    /// `b.args[i].EvalString(ctx, row)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn string(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<Cow<'_, [u8]>>, Error>;
    /// `b.args[i].EvalDecimal(ctx, row)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn decimal(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<MyDecimal>, Error>;
    /// `b.args[i].EvalTime(ctx, row)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn time(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<Time>, Error>;
    /// `b.args[i].EvalDuration(ctx, row)` (the vector driver reads the column with fsp 0:
    /// the value keeps its nanoseconds, which is all a comparison looks at).
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn duration(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<Duration>, Error>;
    /// `b.args[i].EvalJSON(ctx, row)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn json(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<BinaryJSON<'_>>, Error>;
    /// `b.args[i].EvalVectorFloat32(ctx, row)`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn vector_float32(
        &mut self,
        ctx: &dyn EvalContext,
        i: usize,
    ) -> Result<Option<VectorFloat32<'_>>, Error>;
    /// Two arguments lent at once, in Go's order: `b.args[i].EvalVectorFloat32(ctx, row)`,
    /// returning `None` on NULL **before** `b.args[j]` is evaluated, then
    /// `b.args[j].EvalVectorFloat32(ctx, row)` (`None` on NULL). The values borrow from the
    /// argument columns where [`Args::vector_float32`] would, so a body that needs both (the
    /// distance functions) does not copy the first one to end its borrow of `self`.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn vector_float32_pair(
        &mut self,
        ctx: &dyn EvalContext,
        i: usize,
        j: usize,
    ) -> Result<Option<(VectorFloat32<'_>, VectorFloat32<'_>)>, Error>;
}

/// One node of an [`RpnProgram`] (post-order).
#[derive(Debug)]
pub enum RpnNode {
    /// A column of the input chunk, copied (or borrowed) as is.
    ColumnRef {
        /// `Column.Index`.
        index: usize,
    },
    /// A column of the input chunk that Go's `Column.VecEvalXxx` converts: a hybrid
    /// (ENUM/SET/BIT) column read as int or string, or a FLOAT column read as real.
    ColumnConv {
        /// The column.
        expr: ExprRef,
        /// The evaluation type the parent reads (`ETInt`, `ETString` or `ETReal`).
        as_type: EvalType,
    },
    /// A constant: evaluated once per chunk and filled into a column (Go `genVecFromConstExpr`).
    Constant {
        /// The constant.
        expr: ExprRef,
        /// The evaluation type the parent reads.
        as_type: EvalType,
    },
    /// A function call over the last `nargs` results.
    Call {
        /// The function node.
        func: ExprRef,
        /// The number of arguments.
        nargs: usize,
    },
    /// A function call whose Go vector version evaluates its arguments itself and falls back
    /// to its row version ([`SigDesc::args_fallback`]): the arguments are separate programs.
    RowFallback {
        /// The function node.
        func: ExprRef,
        /// The programs of the arguments (read as the signature reads them).
        args: Vec<RpnProgram>,
        /// The fallback rule of the signature.
        rule: ArgsFallback,
    },
}

/// An expression compiled for the vector driver (N4 §3.4). Immutable, `Send + Sync`.
#[derive(Debug)]
pub struct RpnProgram {
    nodes: Vec<RpnNode>,
    ret: EvalType,
    /// The `VecEvalXxx` the caller asked for at the root ([`RpnProgram::compile_as`]):
    /// Go's `EvalExpr` lets the caller pick it (a hybrid expression read as int or string).
    root_as: Option<EvalType>,
}

/// Per-worker state of vector evaluation: reusable intermediate columns and stack.
#[derive(Default)]
pub struct RpnState {
    pool: Vec<Column>,
    stack: Vec<Slot>,
}

impl std::fmt::Debug for RpnState {
    // glue: trait impl
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("RpnState")
            .field("pool", &self.pool.len())
            .finish()
    }
}

// A temporary column moves in and out of the pool; boxing it would add an allocation.
#[allow(clippy::large_enum_variant)]
enum Slot {
    Input(usize),
    Temp(Column),
}

impl RpnProgram {
    /// Compiles `e` for the vector driver.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn compile(e: &ExprRef) -> RpnProgram {
        let mut nodes = Vec::new();
        let ret = static_eval_type(e);
        compile_into(e, ret, &mut nodes);
        RpnProgram {
            nodes,
            ret,
            root_as: None,
        }
    }

    /// Compiles `e` to be read as `et` at the root (Go `expr.VecEvalXxx` for the `Xxx` of
    /// `et`, chosen by the caller as in `EvalExpr`): a column or constant root is read as
    /// `et`, a function root calls the signature's `vecEvalXxx` of `et` (the base error when
    /// the signature has no such vector driver).
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn compile_as(e: &ExprRef, et: EvalType) -> RpnProgram {
        let mut nodes = Vec::new();
        compile_into(e, et, &mut nodes);
        RpnProgram {
            nodes,
            ret: et,
            root_as: Some(et),
        }
    }

    /// The evaluation type of the result.
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn ret_eval_type(&self) -> EvalType {
        self.ret
    }

    /// Evaluates the program on `input` into `result` (Go `VecEvalXxx(ctx, input, result)`).
    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    pub fn eval(
        &self,
        ctx: &dyn EvalContext,
        st: &EvalState,
        rpn: &mut RpnState,
        input: &Chunk,
        result: &mut Column,
    ) -> Result<(), Error> {
        let mut stack = std::mem::take(&mut rpn.stack);
        stack.clear();
        let r = self.eval_inner(ctx, st, rpn, &mut stack, input, result);
        for s in stack.drain(..) {
            if let Slot::Temp(c) = s {
                rpn.pool.push(c);
            }
        }
        rpn.stack = stack;
        r
    }

    // glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
    fn eval_inner(
        &self,
        ctx: &dyn EvalContext,
        st: &EvalState,
        rpn: &mut RpnState,
        stack: &mut Vec<Slot>,
        input: &Chunk,
        result: &mut Column,
    ) -> Result<(), Error> {
        let n = input.num_rows();
        let last = self.nodes.len() - 1;
        for (pos, node) in self.nodes.iter().enumerate() {
            match node {
                RpnNode::ColumnRef { index } => {
                    if pos == last {
                        // The whole expression is a column: Go copies it into the result.
                        let dst = std::mem::replace(result, rt::empty_column());
                        *result = input
                            .column(*index)
                            .copy_reconstruct(input.sel(), Some(dst));
                        return Ok(());
                    }
                    match input.sel() {
                        None => stack.push(Slot::Input(*index)),
                        Some(sel) => {
                            let tmp = rpn.pool.pop();
                            stack.push(Slot::Temp(
                                input.column(*index).copy_reconstruct(Some(sel), tmp),
                            ));
                        }
                    }
                }
                RpnNode::ColumnConv { expr, as_type } => {
                    let c = expr.as_column().expect("ColumnConv holds a Column");
                    if pos == last {
                        return column_conv(ctx, c, *as_type, input, result);
                    }
                    let mut col = rpn.pool.pop().unwrap_or_else(rt::empty_column);
                    let r = column_conv(ctx, c, *as_type, input, &mut col);
                    stack.push(Slot::Temp(col));
                    r?;
                }
                RpnNode::Constant { expr, as_type } => {
                    if pos == last {
                        return rt::fill_constant(ctx, st, expr, *as_type, n, result);
                    }
                    let mut col = rpn.pool.pop().unwrap_or_else(rt::empty_column);
                    let r = rt::fill_constant(ctx, st, expr, *as_type, n, &mut col);
                    stack.push(Slot::Temp(col));
                    r?;
                }
                RpnNode::RowFallback { func, args, rule } => {
                    let mut out = if pos == last {
                        None
                    } else {
                        Some(rpn.pool.pop().unwrap_or_else(rt::empty_column))
                    };
                    let own = sig_eval_type(func);
                    let et = match self.root_as {
                        Some(et) if pos == last => et,
                        _ => own,
                    };
                    let r = {
                        let dst = match out.as_mut() {
                            Some(c) => c,
                            None => &mut *result,
                        };
                        row_fallback_call(ctx, st, rpn, func, args, *rule, et, input, dst)
                    };
                    match out {
                        Some(c) => stack.push(Slot::Temp(c)),
                        None => return r,
                    }
                    r?;
                }
                RpnNode::Call { func, nargs } => {
                    let f = &func
                        .as_scalar_function()
                        .expect("Call node holds a ScalarFunction")
                        .function;
                    let base = stack.len() - nargs;
                    let mut out = if pos == last {
                        None
                    } else {
                        Some(rpn.pool.pop().unwrap_or_else(rt::empty_column))
                    };
                    let r = {
                        let cols: rt::ArgCols<'_> = stack[base..]
                            .iter()
                            .map(|s| match s {
                                Slot::Input(i) => input.column(*i),
                                Slot::Temp(c) => c,
                            })
                            .collect();
                        let dst = match out.as_mut() {
                            Some(c) => c,
                            None => &mut *result,
                        };
                        f.vec_eval(
                            ctx,
                            match self.root_as {
                                Some(et) if pos == last => et,
                                // A signature without drivers of one type: Go calls
                                // VecEvalXxx of the function's result type.
                                _ => f
                                    .sig
                                    .drivers
                                    .eval_type()
                                    .unwrap_or_else(|| f.tp.eval_type()),
                            },
                            n,
                            &cols,
                            dst,
                        )
                    };
                    for s in stack.drain(base..) {
                        if let Slot::Temp(c) = s {
                            rpn.pool.push(c);
                        }
                    }
                    match out {
                        Some(c) => stack.push(Slot::Temp(c)),
                        None => return r,
                    }
                    r?;
                }
            }
        }
        unreachable!("an RPN program ends with its root")
    }
}

// glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
fn compile_into(e: &ExprRef, as_type: EvalType, nodes: &mut Vec<RpnNode>) {
    match &**e {
        Expr::Column(c) => nodes.push(match column_read(c, as_type) {
            ColumnRead::Copy => RpnNode::ColumnRef {
                index: c.index as usize,
            },
            ColumnRead::Convert => RpnNode::ColumnConv {
                expr: Arc::clone(e),
                as_type,
            },
        }),
        Expr::Constant(_) | Expr::CorrelatedColumn(_) => nodes.push(RpnNode::Constant {
            expr: Arc::clone(e),
            as_type,
        }),
        Expr::ScalarFunction(sf) if sf.function.sig.args_fallback != ArgsFallback::None => {
            let drivers = &sf.function.sig.drivers;
            nodes.push(RpnNode::RowFallback {
                func: Arc::clone(e),
                args: sf
                    .function
                    .args
                    .iter()
                    .enumerate()
                    .map(|(i, a)| {
                        let read = drivers
                            .arg_eval_type(i)
                            .unwrap_or_else(|| static_eval_type(a));
                        RpnProgram::compile_as(a, read)
                    })
                    .collect(),
                rule: sf.function.sig.args_fallback,
            });
        }
        Expr::ScalarFunction(sf) => {
            let drivers = &sf.function.sig.drivers;
            for (i, a) in sf.function.args.iter().enumerate() {
                let read = drivers
                    .arg_eval_type(i)
                    .unwrap_or_else(|| static_eval_type(a));
                compile_into(a, read, nodes);
            }
            nodes.push(RpnNode::Call {
                func: Arc::clone(e),
                nargs: sf.function.args.len(),
            });
        }
    }
}

/// The evaluation type a signature's vector driver produces (Go's `VecEvalXxx` of the
/// function's result type when the signature has no single-type drivers).
// glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
fn sig_eval_type(func: &ExprRef) -> EvalType {
    let f = &func
        .as_scalar_function()
        .expect("RowFallback node holds a ScalarFunction")
        .function;
    f.sig
        .drivers
        .eval_type()
        .unwrap_or_else(|| f.tp.eval_type())
}

/// The vector version of a signature that evaluates its arguments itself and falls back to
/// its row version (D08.1 spec §3.6, [`ArgsFallback`]):
///
/// - `SecondArg` (`builtinLogicAndSig` / `builtinLogicOrSig.vecEvalInt`): `args[0]` is
///   evaluated (its error is returned), then `args[1]`; when that fails or adds warnings,
///   the warnings since `args[0]` are truncated and the chunk is evaluated by the row
///   version (`fallbackEvalInt`).
/// - `EveryArg` (`builtinCoalesce*Sig.vecEvalXxx`): every argument in order; when one of
///   them fails or adds warnings (counted from before `args[0]`), the warnings are
///   truncated to before `args[0]` if there are new ones and the chunk is evaluated by the
///   row version (`fallbackEvalXxx`).
///
/// Otherwise the signature's (lazy) vector driver merges the argument columns.
// go: pkg/expression/builtin_op_vec.go builtinLogicAndSig.vecEvalInt L2 (the arguments are RPN sub-programs; the merge is the lazy body's vector driver)
// go: pkg/expression/builtin_op_vec.go builtinLogicOrSig.vecEvalInt L2 (the arguments are RPN sub-programs; the merge is the lazy body's vector driver)
// go: pkg/expression/builtin_op_vec.go builtinLogicAndSig.fallbackEvalInt L1
// go: pkg/expression/builtin_op_vec.go builtinLogicOrSig.fallbackEvalInt L1
#[allow(clippy::too_many_arguments)]
fn row_fallback_call(
    ctx: &dyn EvalContext,
    st: &EvalState,
    rpn: &mut RpnState,
    func: &ExprRef,
    args: &[RpnProgram],
    rule: ArgsFallback,
    et: EvalType,
    input: &Chunk,
    result: &mut Column,
) -> Result<(), Error> {
    let f = &func
        .as_scalar_function()
        .expect("RowFallback node holds a ScalarFunction")
        .function;
    let n = input.num_rows();
    if normalize_et(et) != normalize_et(sig_eval_type(func)) {
        // Go's VecEvalXxx of another type is the base error, before any argument.
        return f.vec_eval(ctx, et, n, &[], result);
    }
    if let ArgsFallback::OwnArgs(vec_fn) = rule {
        let mut eval_arg = |i: usize, c: &mut Column| -> Result<(), Error> {
            args[i].eval(ctx, st, rpn, input, c)
        };
        return vec_fn(f, ctx, st, &mut eval_arg, input, result);
    }
    let before = ctx.warning_count();
    let mut cols: Vec<Column> = Vec::with_capacity(args.len());
    let mut fallback = false;
    let mut err = None;
    for (i, a) in args.iter().enumerate() {
        let mut c = rpn.pool.pop().unwrap_or_else(rt::empty_column);
        let before_arg = ctx.warning_count();
        let r = a.eval(ctx, st, rpn, input, &mut c);
        cols.push(c);
        let after = ctx.warning_count();
        match rule {
            ArgsFallback::SecondArg if i == 0 => {
                if let Err(e) = r {
                    err = Some(e);
                    break;
                }
            }
            ArgsFallback::SecondArg => {
                if r.is_err() || after > before_arg {
                    ctx.truncate_warnings(before);
                    fallback = true;
                    break;
                }
            }
            ArgsFallback::EveryArg => {
                if r.is_err() || after > before {
                    if after > before {
                        ctx.truncate_warnings(before);
                    }
                    fallback = true;
                    break;
                }
            }
            ArgsFallback::None | ArgsFallback::OwnArgs(_) => {
                unreachable!("RowFallback node of a signature without this fallback")
            }
        }
    }
    let r = if let Some(e) = err {
        Err(e)
    } else if fallback {
        eval_rows_into(ctx, st, func, et, input, result)
    } else {
        let refs: Vec<&Column> = cols.iter().collect();
        f.vec_eval(ctx, et, n, &refs, result)
    };
    rpn.pool.extend(cols);
    r
}

/// The `fallbackEvalXxx` of the signatures with [`ArgsFallback`]: the row version on every
/// row of the chunk; the first error is returned.
// go: pkg/expression/builtin_compare_vec_generated.go builtinCoalesceIntSig.fallbackEvalInt L1
// go: pkg/expression/builtin_compare_vec_generated.go builtinCoalesceRealSig.fallbackEvalReal L1
// go: pkg/expression/builtin_compare_vec_generated.go builtinCoalesceDecimalSig.fallbackEvalDecimal L1
// go: pkg/expression/builtin_compare_vec_generated.go builtinCoalesceStringSig.fallbackEvalString L1
// go: pkg/expression/builtin_compare_vec_generated.go builtinCoalesceTimeSig.fallbackEvalTime L1
// go: pkg/expression/builtin_compare_vec_generated.go builtinCoalesceDurationSig.fallbackEvalDuration L1
// go: pkg/expression/builtin_compare_vec_generated.go builtinCoalesceJSONSig.fallbackEvalJSON L1
fn eval_rows_into(
    ctx: &dyn EvalContext,
    st: &EvalState,
    func: &ExprRef,
    et: EvalType,
    input: &Chunk,
    result: &mut Column,
) -> Result<(), Error> {
    let n = input.num_rows();
    macro_rules! fixed {
        ($out:ident, $eval:ident) => {{
            let mut out = rt::$out::new(result, n, &[]);
            for i in 0..n {
                match func.$eval(ctx, st, input.get_row(i))? {
                    Some(v) => out.set(i, v),
                    None => out.set_null(i),
                }
            }
            Ok(())
        }};
    }
    match normalize_et(et) {
        ETInt => fixed!(IntOut, eval_int),
        ETReal => fixed!(RealOut, eval_real),
        ETDecimal => {
            let mut out = rt::DecimalOut::new(result, n, &[]);
            for i in 0..n {
                match func.eval_decimal(ctx, st, input.get_row(i))? {
                    Some(v) => out.set(i, v),
                    None => out.set_null(i),
                }
            }
            Ok(())
        }
        ETDatetime => fixed!(TimeOut, eval_time),
        ETDuration => fixed!(DurationOut, eval_duration),
        ETString => {
            rt::reset_string(result, n);
            for i in 0..n {
                match func.eval_string(ctx, st, input.get_row(i))? {
                    Some(v) => result.append_bytes(&v),
                    None => result.append_null(),
                }
            }
            Ok(())
        }
        ETJson => {
            result.reserve_json(n);
            for i in 0..n {
                match func.eval_json(ctx, st, input.get_row(i))? {
                    Some(v) => result.append_json(&v),
                    None => result.append_null(),
                }
            }
            Ok(())
        }
        ETVectorFloat32 => {
            result.reserve_vector_float32(n);
            for i in 0..n {
                match func.eval_vector_float32(ctx, st, input.get_row(i))? {
                    Some(v) => result.append_vector_float32(&v),
                    None => result.append_null(),
                }
            }
            Ok(())
        }
        other => Err(base_vec_eval_error(other)),
    }
}

/// The evaluation type of `e`'s `RetType` known at build time (a parameter marker's type is
/// fixed when the plan is built, so the field is enough here).
// glue: N4 §3 evaluation framework (signature descriptors, drivers, RPN; M-EVAL)
fn static_eval_type(e: &Expr) -> EvalType {
    match e {
        Expr::Column(c) => c.ret_type.eval_type(),
        Expr::CorrelatedColumn(c) => c.column.ret_type.eval_type(),
        Expr::Constant(c) => c.ret_type.eval_type(),
        Expr::ScalarFunction(f) => f.ret_type().eval_type(),
    }
}

/// How the vector driver reads a column argument.
enum ColumnRead {
    /// Go's `Column.VecEvalXxx` copies the column (`CopyReconstruct`).
    Copy,
    /// Go's `Column.VecEvalXxx` converts it row by row (hybrid, FLOAT).
    Convert,
}

/// Which `Column.VecEvalXxx` branch Go takes when the parent reads `c` as `as_type`.
///
/// Go converts only a hybrid column read as int or string and a FLOAT column read as real;
/// any other read copies the column's storage. A copy whose storage does not hold
/// `as_type` values (a hybrid or FLOAT column read as another type, or a column whose
/// evaluation type differs from `as_type`) would make the signature misread the bytes —
/// Go's function classes never build such a call, so the RPN refuses it here instead of
/// reading float32 as float64 or an ENUM as an int64 (Lucky #82).
// glue: dispatch of Go `Column.VecEvalInt/Real/String` (M-EVAL)
fn column_read(c: &crate::column::Column, as_type: EvalType) -> ColumnRead {
    let tp = c.ret_type.get_type();
    if c.ret_type.hybrid() {
        if as_type == ETInt || as_type == ETString {
            return ColumnRead::Convert;
        }
    } else if tp == tidb_base::mysql::TypeFloat {
        if as_type == ETReal {
            return ColumnRead::Convert;
        }
    } else if normalize_et(c.ret_type.eval_type()) == normalize_et(as_type) {
        // DATE/DATETIME/TIMESTAMP columns all hold Time values (ETTimestamp is read as
        // ETDatetime by Go's VecEvalTime).
        return ColumnRead::Copy;
    }
    panic!(
        "RPN: column {} of type {} (evaluation type {:?}) read as {:?}: Go's Column.VecEval \
         would copy storage that does not hold such values",
        c.index,
        tp,
        c.ret_type.eval_type(),
        as_type
    );
}

/// Go's converting `Column.VecEvalInt/Real/String` (see [`column_read`]).
// glue: dispatch of Go `Column.VecEvalInt/Real/String` (M-EVAL)
fn column_conv(
    ctx: &dyn EvalContext,
    c: &crate::column::Column,
    as_type: EvalType,
    input: &Chunk,
    result: &mut Column,
) -> Result<(), Error> {
    match as_type {
        ETInt => c.vec_eval_int(ctx, input, result),
        ETReal => c.vec_eval_real(ctx, input, result),
        _ => c.vec_eval_string(ctx, input, result),
    }
}
